const slugs=['milk','denim-blue','sand-honey','ice-blue','muted-wine','graphite'];
const menu=document.querySelector('.menu-toggle');menu?.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));document.querySelector('#mobile-nav').hidden=expanded;});
document.querySelectorAll('header nav a').forEach(a=>{if(a.pathname===location.pathname)a.setAttribute('aria-current','page');});
function paletteCard(i){return `<a class="card" href="/${slugs[i]}.html"><div class="card-top"><span>0${i+1} / ${colors[i].ru.toUpperCase()}</span><span>EN + RU</span></div>${board(0,i,'palette'+i)}<div class="card-bottom"><strong>${colors[i].name}</strong><span aria-hidden="true">→</span></div></a>`;}
const catalog=document.querySelector('#catalog-grid');if(catalog){const draw=filter=>{catalog.innerHTML=colors.map((_,i)=>i).filter(i=>filter==='all'||(filter==='light'?[0,2,3].includes(i):[1,4,5].includes(i))).map(paletteCard).join('');};draw('all');document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});draw(b.dataset.filter);}));}
document.querySelectorAll('[data-product]').forEach(el=>{el.innerHTML=board(0,Number(el.dataset.product),'product');});
function getSaved(){try{const data=JSON.parse(localStorage.getItem('form-builds')||'[]');return Array.isArray(data)?data.filter(b=>Number.isInteger(b.c)&&b.c>=0&&b.c<cases.length&&Number.isInteger(b.k)&&b.k>=0&&b.k<colors.length).slice(0,24):[];}catch{return [];}}
const savedGrid=document.querySelector('#saved-grid');if(savedGrid){function drawSaved(){const saved=getSaved();document.querySelector('#saved-status').textContent=saved.length?`${saved.length} saved combination${saved.length===1?'':'s'}.`:'No favorites yet. Explore the configurator to save your first combination.';savedGrid.innerHTML=saved.length?saved.map((b,i)=>`<article class="card"><div class="card-top"><span>YOUR BUILD / ${String(i+1).padStart(2,'0')}</span></div>${savedPreview(b,'saved'+i)}<h3>${b.m==='mountain'?'Matterhorn Edition / '+mountainVariants[b.v||0].name:'Character / '+colors[b.k].name+' / '+cases[b.c].name}</h3><div class="build-tools"><a class="secondary" href="/configure.html?build=${encodeURIComponent(JSON.stringify(b))}">Open build →</a><button class="secondary remove-build" data-index="${i}" data-c="${b.c}" data-k="${b.k}" aria-label="Remove ${colors[b.k].name} on ${cases[b.c].name}">Remove</button></div></article>`).join(''):'<a class="pill" href="/configure.html">Create your first build →</a>';}
 savedGrid.addEventListener('click',e=>{const b=e.target.closest('.remove-build');if(!b)return;try{localStorage.setItem('form-builds',JSON.stringify(getSaved().filter((x,i)=>i!==Number(b.dataset.index))));drawSaved();}catch{document.querySelector('#saved-status').textContent='Unable to update browser storage.';}});drawSaved();}

function savedPreview(b,id){if(b.m==='mountain')return mountainBoard(b.v||0,id);const prior=[legendMode,surface];legendMode=['dual','en','blank'].includes(b.l)?b.l:'dual';surface=b.f==='brushed'?'brushed':'satin';const svg=board(b.c,b.k,id);[legendMode,surface]=prior;return svg;}

